('f15a9923-97c4-5dbd-a8e0-529c9d526a99'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"Here are Ted''s 5 scores prior to tutoring: 70, 70, 80, 75, 80. Here are his 2 scores after tutoring: 90, 95. By how much did the median and the mean change after tutoring?"'::jsonb,'[{"key":"A","text":"The median remained the same. The mean increased by 5"},{"key":"B","text":"The median increased by 5. The mean remained the same"},{"key":"C","text":"The median and the mean both increased by 5"},{"key":"D","text":"The median and the mean both remained the same"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"extra.md","source_sha256":"84ca68dc45b2ef2b31ffef4bf4fca4ef2cb3beb1365109214d65e6b7240c41ea","source_question_id":"E-22","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from extra.md (E-22)."'::jsonb),
