('cfb8a43c-5a68-5964-ae28-aca68908ee6c'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"The student council has $215 to purchase juice and candy bars for a school event. Each bottle of juice costs $0.45 and each candy bar costs $0.50. Which of the following inequalities includes all possible combinations of bottles of juice (x) and candy bars (y) that the student council can purchase?"'::jsonb,'[{"key":"A","text":"0.45x + 0.5y ≥ 215"},{"key":"B","text":"0.45x + 0.5y ≤ 215"},{"key":"C","text":"0.95(x + y) ≥ 215"},{"key":"D","text":"0.95(x + y) ≤ 215"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"extra.md","source_sha256":"84ca68dc45b2ef2b31ffef4bf4fca4ef2cb3beb1365109214d65e6b7240c41ea","source_question_id":"E-24","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from extra.md (E-24)."'::jsonb),
