('22212e7f-f204-5c50-8a47-f997ae826929'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"The trajectory of a potato launched from a potato cannon on the ground at an angle of 45 degrees with an initial speed of 65 meters per second can be modeled by the parabola f(x) = x − 0.0023x² where the x-axis is the ground. Find the height of the highest point of the trajectory and the horizontal distance the potato travels before hitting the ground.\n[Figure: graph of the parabola on axes Height (m) vs Horizontal Distance (m), peaking near (217, 109) and landing near x = 435.]"'::jsonb,'[{"key":"A","text":"height: 109 m; distance: 435 m"},{"key":"B","text":"height: 121 m; distance: 418 m"},{"key":"C","text":"height: 118 m; distance: 421 m"},{"key":"D","text":"height: 102 m; distance: 409 m"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"hard.md","source_sha256":"b0a0fb727049e45d7472b3b33f3d1323a44072e91a6e39f7f1a553d9099f493a","source_question_id":"H-16","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/H-16.png","image_alt":"Original graph, diagram, or table for H-16","visual_verified":true}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from hard.md (H-16)."'::jsonb),
