('b6c57e4d-f31f-531c-9085-3a21cf3e9203'::uuid,'est','"Solid Geometry & Volume"'::jsonb,'medium','mcq','"What is the surface area of a sphere whose largest cross section has an area that measures 16π units²?"'::jsonb,'[{"key":"A","text":"64π units²"},{"key":"B","text":"256π/3 units²"},{"key":"C","text":"1,024π units²"},{"key":"D","text":"It is impossible to determine from the given information"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"hard.md","source_sha256":"b0a0fb727049e45d7472b3b33f3d1323a44072e91a6e39f7f1a553d9099f493a","source_question_id":"H-40","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Solid Geometry & Volume"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from hard.md (H-40)."'::jsonb),
('60c5d316-8039-5066-a5e0-be9e4ea18316'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"Anja decides to track how long it takes her to get to school each day. After tracking her drive five times, Anja finds that it takes her an average of 27 minutes to get to school each day. The quickest Anja can get to school, if she encounters no traffic, is in 23 minutes. If on the first day, Anja drove to school in 31 minutes, what is the longest possible time it took Anja to drive to school during those five days?"'::jsonb,'[{"key":"A","text":"29 minutes"},{"key":"B","text":"31 minutes"},{"key":"C","text":"33 minutes"},{"key":"D","text":"35 minutes"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"hard.md","source_sha256":"b0a0fb727049e45d7472b3b33f3d1323a44072e91a6e39f7f1a553d9099f493a","source_question_id":"H-41","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from hard.md (H-41)."'::jsonb),
