('dc3afa9c-de34-5ace-ad0e-2e76090fa557'::uuid,'est','"Triangles, Trigonometry & Similarity"'::jsonb,'easy','mcq','"Two sides of a triangle have lengths 7 and 2. Which of the following could be the perimeter of this triangle?"'::jsonb,'[{"key":"A","text":"9"},{"key":"B","text":"11"},{"key":"C","text":"14"},{"key":"D","text":"16"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"hard.md","source_sha256":"b0a0fb727049e45d7472b3b33f3d1323a44072e91a6e39f7f1a553d9099f493a","source_question_id":"H-43","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from hard.md (H-43)."'::jsonb),
('1ab08bd8-561a-5793-ad37-3cbf34bee937'::uuid,'est','"Plane Geometry, Measurement & Transformations"'::jsonb,'medium','mcq','"The figure was formed by combining two equal squares, such that a vertex of one square is at the center of the other square. The area of the shaded region is x. In terms of x, what is the area of the unshaded region?\n[Figure: two equal overlapping squares; the overlap (unshaded) is a smaller square with right angles marked; the rest of both squares is shaded.]"'::jsonb,'[{"key":"A","text":"6x/7"},{"key":"B","text":"3x/4"},{"key":"C","text":"x/6"},{"key":"D","text":"x/7"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"hard.md","source_sha256":"b0a0fb727049e45d7472b3b33f3d1323a44072e91a6e39f7f1a553d9099f493a","source_question_id":"H-44","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Plane Geometry, Measurement & Transformations","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/H-44.png","image_alt":"Original graph, diagram, or table for H-44","visual_verified":true}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from hard.md (H-44)."'::jsonb),
('fea71110-5102-5f5b-88fa-7d4b3c38f7e9'::uuid,'est','"Polynomials & Quadratic Functions"'::jsonb,'medium','mcq','"For what value of c will the graphs of y = 2x² − 36x + c and y = 2(x − 9)² − 18 be the same?"'::jsonb,'[{"key":"F","text":"63"},{"key":"G","text":"−180"},{"key":"H","text":"99"},{"key":"J","text":"144"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-02","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Polynomials & Quadratic Functions"}'::jsonb,'"J"'::jsonb,'"Source-keyed answer from moh.md (MA-02)."'::jsonb),
('17d0b302-b0eb-5616-90e2-c8e43b1448dd'::uuid,'est','"Plane Geometry, Measurement & Transformations"'::jsonb,'medium','mcq','"The rectangular patio shown in the diagram below is enclosed on three sides by a fence.\n[Figure: Rectangular patio with length l (top side) and width w (two sides) fenced; the fourth side borders a house.]\nThe area of this patio is no more than 400 square feet. The total length of the three sides of this fence is no more than 60 feet. Which system of inequalities can be used to find values of l, the patio''s length, and w, the patio''s width, that will satisfy these conditions?"'::jsonb,'[{"key":"A","text":"l + 2w ≤ 60 ; lw ≤ 400"},{"key":"B","text":"2l + 2w ≤ 60 ; lw ≤ 400"},{"key":"C","text":"l + 2w ≥ 60 ; lw ≥ 400"},{"key":"D","text":"2l + 2w ≥ 60 ; lw ≥ 400"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-03","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Plane Geometry, Measurement & Transformations","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/MA-03.png","image_alt":"Original graph, diagram, or table for MA-03","visual_verified":true}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from moh.md (MA-03)."'::jsonb),
('62dd8fd2-5ff4-5928-83ce-ca238fc9082b'::uuid,'est','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"The graph of the quadratic function f is shown on the grid below.\n[Figure: Upward parabola crossing the x-axis at about 7.5 and 17.5, vertex near (12.5, −25).]\nWhat does the solution set for f(x) = 0 appear to be?"'::jsonb,'[{"key":"F","text":"{12.5}"},{"key":"G","text":"{12.5, −25}"},{"key":"H","text":"{7.5, 17.5}"},{"key":"J","text":"{7.5, 12.5, 17.5}"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-04","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/MA-04.png","image_alt":"Original graph, diagram, or table for MA-04","visual_verified":true}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from moh.md (MA-04)."'::jsonb),
('d7d7bb53-434c-58f8-aa35-335de0a30267'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"The cost of printing cookbooks is $2.09 per book plus a one-time setup fee of $349. All taxes are included. Which of the following functions models a(x), the average cost per book of printing x cookbooks?"'::jsonb,'[{"key":"A","text":"a(x) = 2.09x + 349/x"},{"key":"B","text":"a(x) = (2.09x + 349)/x"},{"key":"C","text":"a(x) = (2.09 + 349)/(2.09x)"},{"key":"D","text":"a(x) = (2.09x + 349)/(2.09x)"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-05","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from moh.md (MA-05)."'::jsonb),
('27fc68f6-1af2-5bfc-aebc-0a0443374d77'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'hard','mcq','"Which graph best represents the parent function of y = 4^(x+3) ?\n[Figure: Four graphs. F: increasing exponential through (0,1), asymptote y=0 on the left. G: increasing exponential passing below the origin, asymptote y=−1. H: decreasing exponential approaching y=0 on the right. J: decreasing curve below the x-axis approaching y=−1.]"'::jsonb,'[{"key":"F","text":"Graph F"},{"key":"G","text":"Graph G"},{"key":"H","text":"Graph H"},{"key":"J","text":"Graph J"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-06","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/MA-06.png","image_alt":"Original graph, diagram, or table for MA-06","visual_verified":true}'::jsonb,'"F"'::jsonb,'"Source-keyed answer from moh.md (MA-06)."'::jsonb),
('da6ade77-b738-5fb3-b696-79bccf1d0a16'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"There were 417 cell phones sold at an electronics store in January. Since then, cell phone sales at this store have increased at a rate of 3.75% per month. At this rate of growth, which function can be used to determine the monthly cell phone sales m months after January?"'::jsonb,'[{"key":"A","text":"p(m) = 417(0.0375)^m"},{"key":"B","text":"p(m) = 417(1.0375)^m"},{"key":"C","text":"p(m) = 417(0.9625)^(m+1)"},{"key":"D","text":"p(m) = 417(0.0375)^(m+1)"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-07","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from moh.md (MA-07)."'::jsonb),
('9f5430a1-6089-5328-9997-715c99190b44'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'hard','mcq','"The graph of the function f is shown on the grid below.\n[Figure: Rational function with vertical asymptotes at x = −2 and x = 2; upper branches above y ≈ 1 for x < −2 and x > 2; middle branch below the x-axis between −2 and 2.]\nBased on the graph, for what values of x is f(x) > 0 ?"'::jsonb,'[{"key":"F","text":"All real numbers greater than 0"},{"key":"G","text":"All real numbers greater than 1"},{"key":"H","text":"All real numbers less than −2 or greater than 2"},{"key":"J","text":"All real numbers greater than −2 and less than 2"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-08","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/MA-08.png","image_alt":"Original graph, diagram, or table for MA-08","visual_verified":true}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from moh.md (MA-08)."'::jsonb),
('204ea363-63ad-54b2-85df-31cdeb753523'::uuid,'est','"Plane Geometry, Measurement & Transformations"'::jsonb,'medium','mcq','"The sum of a number, n, and its square root can be represented by the equation y = n + √n. If y = 20, which of the following is true?"'::jsonb,'[{"key":"A","text":"n = 16"},{"key":"B","text":"n = 4"},{"key":"C","text":"n = 16 and n = 25"},{"key":"D","text":"n = 4 and n = 5"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-09","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Plane Geometry, Measurement & Transformations"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from moh.md (MA-09)."'::jsonb),
('515ae9bb-7591-5ae1-93ce-4b1861316881'::uuid,'est','"Solid Geometry & Volume"'::jsonb,'medium','mcq','"The graph of the function h was obtained from the graph of the function g using a composite transformation, as shown below.\n[Figure: Dashed curve g with closed endpoint (−6, −3) and open endpoint (−2, 6); solid curve h with closed endpoint (−2, −5) and open endpoint (2, 4).]\nWhich equation can be used to describe h(x) in terms of g(x)?"'::jsonb,'[{"key":"F","text":"h(x) = g(x + 4) + 2"},{"key":"G","text":"h(x) = g(x + 4) − 2"},{"key":"H","text":"h(x) = g(x − 4) − 2"},{"key":"J","text":"h(x) = g(x − 4) + 2"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-10","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Solid Geometry & Volume","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/MA-10.png","image_alt":"Original graph, diagram, or table for MA-10","visual_verified":true}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from moh.md (MA-10)."'::jsonb),
('49f2573a-8f5c-51a7-b05c-d1b6aeccbcf7'::uuid,'est','"Functions, Transformations & Graphs"'::jsonb,'medium','mcq','"A craftsman wants to spend less than $300 on supplies for making bracelets and necklaces. Supplies for 1 bracelet cost $4, and supplies for 1 necklace cost $9. This relationship is shown in the graph below.\n[Figure: \"Jewelry Supplies\" graph — shaded region below the dashed line from (0, 33) to (75, 0); x-axis: Supplies for Bracelets; y-axis: Supplies for Necklaces.]\nThe craftsman wants to make at least 10 more bracelets than necklaces. Which of the following is a reasonable solution?"'::jsonb,'[{"key":"A","text":"25 bracelets and 20 necklaces"},{"key":"B","text":"30 bracelets and 15 necklaces"},{"key":"C","text":"40 bracelets and 20 necklaces"},{"key":"D","text":"15 bracelets and 25 necklaces"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-11","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Functions, Transformations & Graphs","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/MA-11.png","image_alt":"Original graph, diagram, or table for MA-11","visual_verified":true}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from moh.md (MA-11)."'::jsonb),
('8b3e9b48-00f5-5280-adaa-85a7428f6599'::uuid,'est','"Polynomials & Quadratic Functions"'::jsonb,'medium','mcq','"Which function''s graph has a vertex at (3, 5) and contains the point (5, 13)?"'::jsonb,'[{"key":"F","text":"y = (1/10)(x + 3)² − 5"},{"key":"G","text":"y = (1/10)(x − 3)² − 5"},{"key":"H","text":"y = 2(x − 3)² + 5"},{"key":"J","text":"y = 2(x + 3)² + 5"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-12","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Polynomials & Quadratic Functions"}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from moh.md (MA-12)."'::jsonb),
('afde8a23-6df0-5aa5-8f13-32d7dd1c8f1c'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'medium','numeric','"What value of p makes the equation below true?\n19/(4p − 1) = 5\nRecord your answer and fill in the bubbles on your answer document. [Griddable — answer: 1.2]"'::jsonb,'[]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-13","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions"}'::jsonb,'"1.2"'::jsonb,'"Source-keyed answer from moh.md (MA-13)."'::jsonb),
('07931921-276e-5c7c-80d9-7b3df878d1ca'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"An object is launched into the air. The table below shows the object''s height above the ground at various times.\n[Table — Height vs. Time (Elapsed Time s | Height m): 1|78, 2|109, 3|131, 4|143, 5|145, 6|137]\nBased on the data in the table, which of the following is closest to the object''s height above the ground 9 seconds after being launched?"'::jsonb,'[{"key":"A","text":"110 m"},{"key":"B","text":"55 m"},{"key":"C","text":"10 m"},{"key":"D","text":"95 m"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-15","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from moh.md (MA-15)."'::jsonb),
('7669abde-7930-5395-8d5e-cb2d3a04b15e'::uuid,'est','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"A quadratic function is graphed on the grid below.\n[Figure: Upward parabola with vertex (−5, −8) and x-intercepts −7 and −3.]\nIf this function is written in the form y = a(x − h)² + k, what is the value of a?"'::jsonb,'[{"key":"F","text":"−3"},{"key":"G","text":"−8"},{"key":"H","text":"5"},{"key":"J","text":"2"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-16","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/MA-16.png","image_alt":"Original graph, diagram, or table for MA-16","visual_verified":true}'::jsonb,'"J"'::jsonb,'"Source-keyed answer from moh.md (MA-16)."'::jsonb),
('be5d603a-ac3a-5b80-b210-338925e28fb6'::uuid,'est','"Plane Geometry, Measurement & Transformations"'::jsonb,'medium','mcq','"Which two transformations can be used to obtain the graph of g(x) = −√(x − c) from the graph of f(x) = √x if c > 0 ?"'::jsonb,'[{"key":"A","text":"A translation to the right c units followed by a reflection across the x-axis"},{"key":"B","text":"A translation to the left c units followed by a reflection across the x-axis"},{"key":"C","text":"A translation to the right c units followed by a reflection across the y-axis"},{"key":"D","text":"A translation to the left c units followed by a reflection across the y-axis"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-17","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Plane Geometry, Measurement & Transformations"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from moh.md (MA-17)."'::jsonb),
('9b34cdaf-d253-58a4-9568-2e4b028d904e'::uuid,'est','"Polynomials & Quadratic Functions"'::jsonb,'medium','mcq','"Which of the following is a solution to 10x² − x = 3 ?"'::jsonb,'[{"key":"F","text":"−1/5"},{"key":"G","text":"3/5"},{"key":"H","text":"−3/2"},{"key":"J","text":"1/2"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-18","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Polynomials & Quadratic Functions"}'::jsonb,'"G"'::jsonb,'"Source-keyed answer from moh.md (MA-18)."'::jsonb),
('e6cef075-ddbf-5890-8452-59daf545ae70'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','numeric','"What is the x-value of the solution to the system of equations below?\nx + y + z = 8\nx + 2y = 6\ny + z = 4\nRecord your answer and fill in the bubbles on your answer document. [Griddable — answer: 4]"'::jsonb,'[]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-19","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"4"'::jsonb,'"Source-keyed answer from moh.md (MA-19)."'::jsonb),
('088a3922-48b5-593d-bf64-83b7ec0c9dad'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"The function below can be used to model the area of a rectangle in square inches, A, if the rectangle has a perimeter of 72 inches and a width of w inches.\nA = 36w − w²\nIn this situation, which of the following best describes the domain of the function?"'::jsonb,'[{"key":"F","text":"0 < w < 6"},{"key":"G","text":"0 < w < 72"},{"key":"H","text":"0 < w < 18"},{"key":"J","text":"0 < w < 36"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-20","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"J"'::jsonb,'"Source-keyed answer from moh.md (MA-20)."'::jsonb),
('a63ec5fe-d8ed-5e0a-9e95-47837c666247'::uuid,'est','"Polynomials & Quadratic Functions"'::jsonb,'medium','mcq','"A table of values for the quadratic function g is shown below.\n[Table — x | g(x): −1|−55, 2|−16, 5|5, 6|8, 9|5, 10|0, 12|−16, 14|−40]\nWhich of the following statements about the graph of g are true?\nI. The graph has a line of symmetry at x = 7.\nII. The graph has a y-intercept at (0, −40).\nIII. The graph has an x-intercept at (4, 0).\nIV. The graph has a vertex at (6, 8)."'::jsonb,'[{"key":"F","text":"I and II only"},{"key":"G","text":"III and IV only"},{"key":"H","text":"I, II, and III only"},{"key":"J","text":"I, II, III, and IV"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-22","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Polynomials & Quadratic Functions"}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from moh.md (MA-22)."'::jsonb),
('5f0d3411-1e16-586c-abd1-8753a389f24f'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"The product of 2 consecutive odd integers is 483. If x represents the smaller integer, which equation can be used to find both integers?"'::jsonb,'[{"key":"A","text":"x(x + 2) = 483"},{"key":"B","text":"x(x + 1) = 483"},{"key":"C","text":"x(x + 3) = 483"},{"key":"D","text":"(x + 1)(x + 2) = 483"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-23","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from moh.md (MA-23)."'::jsonb),
('e9e4fcfc-2a65-5891-bbeb-b04b25b48fab'::uuid,'est','"Functions, Transformations & Graphs"'::jsonb,'medium','numeric','"If 5 is an element in the domain of f(x) = (7x − 22)/4, what is the corresponding element in the range?\nRecord your answer and fill in the bubbles on your answer document. [Griddable — answer: 3.25]"'::jsonb,'[]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-24","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Functions, Transformations & Graphs"}'::jsonb,'"3.25"'::jsonb,'"Source-keyed answer from moh.md (MA-24)."'::jsonb),
('ff9abe8a-42b3-5076-9aa1-0c1556856184'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"An antibiotic is introduced into a colony of 12,000 bacteria during a laboratory experiment. The function below can be used to model the number of bacteria in the colony after m minutes.\nn(m) = 12,000(0.851)^(m/10)\nWhich value is closest to the amount of time needed for the population of the colony to drop to 8,000 bacteria?"'::jsonb,'[{"key":"F","text":"11 min"},{"key":"G","text":"25 min"},{"key":"H","text":"8 min"},{"key":"J","text":"42 min"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-26","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"G"'::jsonb,'"Source-keyed answer from moh.md (MA-26)."'::jsonb),
('8670003d-46d6-5d2e-ad24-3948b65ecd93'::uuid,'est','"Polynomials & Quadratic Functions"'::jsonb,'medium','mcq','"The table below shows values of a quadratic function g.\n[Table — x | g(x): −5|−11, −4|8, −3|21, −2|28, −1|29, 0|24, 1|13, 2|−4, 3|−27]\nBased on the table, in which interval can a solution to g(x) = 0 be found?"'::jsonb,'[{"key":"A","text":"−5 < x < −4"},{"key":"B","text":"−2 < x < −1"},{"key":"C","text":"−1 < x < 1"},{"key":"D","text":"2 < x < 3"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-27","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Polynomials & Quadratic Functions"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from moh.md (MA-27)."'::jsonb),
('9bbb1e74-2ada-516f-b340-c50dafb60c76'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"The given function models the equivalent resistance in ohms, R, when a fixed 9-ohm resistor is connected in parallel with a variable resistor of x ohms.\nR = 9x/(9 + x)\nWhich value of x is closest to the number of ohms needed in the variable resistor for there to be an equivalent resistance, R, of 6.4 ohms?"'::jsonb,'[{"key":"F","text":"15.4"},{"key":"G","text":"57.6"},{"key":"H","text":"3.7"},{"key":"J","text":"22.2"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-28","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"J"'::jsonb,'"Source-keyed answer from moh.md (MA-28)."'::jsonb),
('f735beb4-7339-57bf-994f-dca9749f060f'::uuid,'est','"Functions, Transformations & Graphs"'::jsonb,'medium','mcq','"For the functions h and g, which statement is true if h(x) = g(x + 14) − 12 ?"'::jsonb,'[{"key":"A","text":"The graph of h is the result of the graph of g being translated right 14 units and down 12 units."},{"key":"B","text":"The graph of h is the result of the graph of g being translated left 14 units and down 12 units."},{"key":"C","text":"The graph of h is the result of the graph of g being translated right 14 units and up 12 units."},{"key":"D","text":"The graph of h is the result of the graph of g being translated left 14 units and up 12 units."}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-29","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Functions, Transformations & Graphs"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from moh.md (MA-29)."'::jsonb),
('ea8f0c7d-f22f-56cf-b1ee-6193f4ce4011'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'hard','mcq','"The graph of the exponential function f is shown on the grid below.\n[Figure: Increasing exponential passing through (−2, 16) and (0, 32), asymptote y = 0 on the left.]\nFor what values of x is f(x) > 16 ?"'::jsonb,'[{"key":"F","text":"x > −2"},{"key":"G","text":"x > 0"},{"key":"H","text":"−2 < x < 2"},{"key":"J","text":"∞ < x < −2"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-30","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/MA-30.png","image_alt":"Original graph, diagram, or table for MA-30","visual_verified":true}'::jsonb,'"F"'::jsonb,'"Source-keyed answer from moh.md (MA-30)."'::jsonb),
('16596a28-8159-506f-b514-7baa3c82fd02'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'medium','numeric','"What value of n makes √(10 − 3n) = 7 true?\nRecord your answer and fill in the bubbles on your answer document. [Griddable — answer: −13]"'::jsonb,'[]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-31","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions"}'::jsonb,'"−13"'::jsonb,'"Source-keyed answer from moh.md (MA-31)."'::jsonb),
('2921d30b-6a6e-57a6-8ec0-d92bf94bb0a9'::uuid,'est','"Plane Geometry, Measurement & Transformations"'::jsonb,'medium','mcq','"Which equation has the same graph as 2x² − 4x − y + 11 = 0 ?"'::jsonb,'[{"key":"F","text":"y = (2x − 1)² + 9"},{"key":"G","text":"y = (2x − 1)² + 13"},{"key":"H","text":"y = 2(x − 1)² + 9"},{"key":"J","text":"y = 2(x − 1)² + 13"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-32","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Plane Geometry, Measurement & Transformations"}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from moh.md (MA-32)."'::jsonb),
('06d34ef2-4d00-5d0e-aa9a-30b2939cdb74'::uuid,'est','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"A sector of a circle is shown below.\n[Figure: Quarter-circle sector with both radii labeled r and a right angle at the center.]\nThe area, A, of the sector is π/4 times the square of the radius, r. Which graph represents this relationship?\n[Figure: Four graphs of Area vs Radius. A: decreasing curve. B: increasing curve bending upward from the origin. C: decreasing curve leveling off. D: increasing curve leveling off.]"'::jsonb,'[{"key":"A","text":"Graph A"},{"key":"B","text":"Graph B"},{"key":"C","text":"Graph C"},{"key":"D","text":"Graph D"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-33","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/MA-33.png","image_alt":"Original graph, diagram, or table for MA-33","visual_verified":true}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from moh.md (MA-33)."'::jsonb),
('773c24e7-0156-51e9-b0f2-c337172377c2'::uuid,'est','"Triangles, Trigonometry & Similarity"'::jsonb,'medium','mcq','"The hypotenuse of a right triangle is 17 inches long. A leg of this triangle, y, is 1 inch less than twice the length of the other leg, x. Which system of equations can be used to determine the lengths of the 2 legs of this right triangle in inches?"'::jsonb,'[{"key":"F","text":"x² + y² = 289 ; y = 2x − 1"},{"key":"G","text":"x² + y² = 289 ; 2x + y = 1"},{"key":"H","text":"x + y = 17 ; y = 2x − 1"},{"key":"J","text":"x + y = 17 ; 2x + y = 1"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-34","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity"}'::jsonb,'"F"'::jsonb,'"Source-keyed answer from moh.md (MA-34)."'::jsonb),
('fdb13734-552b-5f47-8664-55850b98b211'::uuid,'est','"Sequences, Complex Numbers & Advanced Algebra"'::jsonb,'medium','mcq','"What is the solution set for x² + 4 = 6x ?"'::jsonb,'[{"key":"A","text":"{−3 ± i√14}"},{"key":"B","text":"{−3 ± √5}"},{"key":"C","text":"{3 ± i√14}"},{"key":"D","text":"{3 ± √5}"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-35","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Sequences, Complex Numbers & Advanced Algebra"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from moh.md (MA-35)."'::jsonb),
('b1e1ab4a-98b6-5a0d-a1d0-c00fba46b463'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"Each year an architecture firm employs senior interns and junior interns. Senior interns receive $400 per week, and junior interns receive $300 per week. This year a minimum of 7 but no more than 13 interns will be hired. The amount spent per week on interns cannot exceed $4,000. Which statement about this situation is not true?"'::jsonb,'[{"key":"A","text":"The architecture firm can employ 13 junior interns."},{"key":"B","text":"The architecture firm can employ 4 senior interns and 7 junior interns."},{"key":"C","text":"If both types of interns are hired, the firm will spend a minimum of $2,200 per week on interns."},{"key":"D","text":"If both types of interns are hired, the firm will spend a maximum of $3,800 per week on interns."}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-37","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from moh.md (MA-37)."'::jsonb),
('2d52ccaa-0021-5cbd-a93f-aacb527d9c79'::uuid,'est','"Sequences, Complex Numbers & Advanced Algebra"'::jsonb,'medium','mcq','"Which table contains only values in the solution set for y ≤ √(25 − x) + 11 ?\n[Table F: (−24,19), (−11,17), (9,10), (24,9)]\n[Table G: (−24,18), (−11,16), (9,11), (24,9)]\n[Table H: (−24,19), (−11,18), (9,−18), (24,−19)]\n[Table J: (−24,9), (−11,10), (9,15), (24,17)]"'::jsonb,'[{"key":"F","text":"Table F"},{"key":"G","text":"Table G"},{"key":"H","text":"Table H"},{"key":"J","text":"Table J"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-38","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Sequences, Complex Numbers & Advanced Algebra"}'::jsonb,'"G"'::jsonb,'"Source-keyed answer from moh.md (MA-38)."'::jsonb)
), inserted as (
 insert into public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
 select i.id,i.track_id,i.topic #>> '{}',i.difficulty,i.type,i.stem #>> '{}',i.choices,i.assets
 from imported i
 where not exists (select 1 from public.questions e where e.track_id='est' and lower(regexp_replace(e.stem,'[^a-z0-9]+','','g'))=lower(regexp_replace(i.stem #>> '{}','[^a-z0-9]+','','g')))
 on conflict (id) do update set topic=excluded.topic,difficulty=excluded.difficulty,type=excluded.type,stem=excluded.stem,choices=excluded.choices,assets=excluded.assets
 returning id
)
insert into public.question_keys(question_id,correct,explanation)
select i.id,i.correct,i.explanation #>> '{}' from imported i join public.questions q on q.id=i.id
on conflict (question_id) do update set correct=excluded.correct, explanation=excluded.explanation;
commit;
